   104→#[test]
   105→fn test_power_zone_colors_defined() {
   106→    assert_eq!(POWER_ZONE_COLORS.len(), 7);
   107→
   108→    // Verify all colors are different
   109→    for (i, c1) in POWER_ZONE_COLORS.iter().enumerate().take(7) {
   110→        for (j, c2) in POWER_ZONE_COLORS
   111→            .iter()
   112→            .enumerate()
   113→            .skip(i + 1)
   114→            .take(7 - i - 1)
   115→        {
   116→            assert!(
   117→                c1.r != c2.r || c1.g != c2.g || c1.b != c2.b,
   118→                "Zone {} and {} should have different colors",
   119→                i + 1,
   120→                j + 1
   121→            );
   122→        }
   123→    }
   124→}
