   150→#[test]
   151→fn test_hr_zones_from_karvonen() {
   152→    // Max HR 180, Resting HR 60 => HRR = 120
   153→    let zones = HRZones::from_hr(180, 60);
   154→
   155→    // Z1: 50-60% HRR = 60 + (120 * 0.5-0.6) = 120-132 bpm
   156→    assert_eq!(zones.z1_recovery.min_bpm, 120);
   157→    assert_eq!(zones.z1_recovery.max_bpm, 132);
   158→    assert_eq!(zones.z1_recovery.zone, 1);
   159→
   160→    // Z2: 60-70% HRR = 60 + (120 * 0.6-0.7) = 132-144 bpm
   161→    assert_eq!(zones.z2_aerobic.min_bpm, 132);
   162→    assert_eq!(zones.z2_aerobic.max_bpm, 144);
   163→
   164→    // Z3: 70-80% HRR = 60 + (120 * 0.7-0.8) = 144-156 bpm
   165→    assert_eq!(zones.z3_tempo.min_bpm, 144);
   166→    assert_eq!(zones.z3_tempo.max_bpm, 156);
   167→
   168→    // Z4: 80-90% HRR = 60 + (120 * 0.8-0.9) = 156-168 bpm
   169→    assert_eq!(zones.z4_threshold.min_bpm, 156);
   170→    assert_eq!(zones.z4_threshold.max_bpm, 168);
   171→
   172→    // Z5: 90-100% HRR = 60 + (120 * 0.9-1.0) = 168-180 bpm
   173→    assert_eq!(zones.z5_maximum.min_bpm, 168);
   174→    assert_eq!(zones.z5_maximum.max_bpm, 180);
   175→}
